/** Generated by `build/droppen-plugins.ts` from the distribution manifest. */
declare module "virtual:droppen/bundled-plugins" {
  import type { LocalizedText, PluginDefinition } from "@droppen/plugin-sdk";

  /** A bundled plugin's manifest, as the build read it from its package. */
  export interface BundledManifest {
    id: string;
    version: string;
    name: LocalizedText;
    engines: { droppen: string };
    permissions: string[];
    aliases: string[];
    defaultEnabled: boolean;
    package: string;
  }

  export interface BundledPlugin {
    id: string;
    manifest: BundledManifest;
    /** The plugin's entry chunk; fetched only once the plugin is enabled. */
    load: () => Promise<{ default: PluginDefinition }>;
  }

  /** The distribution's name: `public` for the open build. */
  export const distribution: string;
  export const bundledPlugins: BundledPlugin[];
}
